This target provides address autocomplete suggestions for address forms at checkout and does not support rendering UI components.

[purchase.checkout.address-autocomplete.suggest](https://shopify.dev/docs/api/checkout-ui-extensions/latest/targets)

## /extensions/address-autocomplete/src/suggest.js

```javascript
export default async () => {
    const {field, value, selectedCountryCode} = shopify.target;


    const response = await fetchSuggestions(
      field,
      value,
      selectedCountryCode,
      shopify.signal
    );
    const { result } = await response.json();


    const suggestions = result.suggestions.map((suggestion) => {
      return {
        id: suggestion.global_address_key,
        label: suggestion.text,
        matchedSubstrings: suggestion.matched,
        formattedAddress: suggestion.formattedAddress,
      };
    });


    return { suggestions };
  }


